insert into public.transactions
  (id, tx_date, tx_type, amount_eur, orig_amount, orig_currency, fx_rate, fx_provider, category_id, paid_by, memo, bemju, legacy_no, source, created_by)
select gen_random_uuid(), v.d::date, v.t, v.a::numeric, v.oa::numeric, v.oc, v.fr::numeric,
       case when v.oc = 'KRW' then 'legacy' end, c.id, v.p, v.m, nullif(v.b,''), v.no::int, 'import',
