-- 검증: 아래 숫자가 리포트와 일치해야 함
select count(*) as imported_total,
       round(sum(amount_eur) filter (where tx_type='expense'), 2) as expense_sum,
       round(sum(amount_eur) filter (where tx_type='income'), 2) as income_sum,
       round(sum(amount_eur) filter (where tx_type='transfer'), 2) as transfer_sum
from public.transactions where source = 'import';
